import{_ as t,o as r,c as i,a3 as a}from"./chunks/framework.CchDE9cb.js";const h=JSON.parse('{"title":"Security control inventories","description":"Entry points, sensitive-data classes, the cryptographic inventory, service limits and audit events — dated 2026-07-14.","frontmatter":{"title":"Security control inventories","description":"Entry points, sensitive-data classes, the cryptographic inventory, service limits and audit events — dated 2026-07-14."},"headers":[],"relativePath":"security/control-inventories.md","filePath":"security/control-inventories.md","lastUpdated":1785253498000}'),d={name:"security/control-inventories.md"};function n(o,e,s,c,l,p){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="security-control-inventories" tabindex="-1">Security control inventories <a class="header-anchor" href="#security-control-inventories" aria-label="Permalink to &quot;Security control inventories&quot;">​</a></h1><p>Version: 2026-07-14. These inventories support ASVS architecture requirements; they are not a substitute for deployment-specific data classification, key inventory or log-retention policy.</p><h2 id="entry-points-and-untrusted-input" tabindex="-1">Entry points and untrusted input <a class="header-anchor" href="#entry-points-and-untrusted-input" aria-label="Permalink to &quot;Entry points and untrusted input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Input</th><th>Format and limit</th><th>Trusted enforcement</th><th>Security treatment</th></tr></thead><tbody><tr><td>Tenant API route/body/query/path</td><td>JSON and bounded strings/arrays; explicit route schemas/codecs</td><td>Fastify API and shared domain</td><td>authentication, per-operation membership/action check, allowlisted tables/fields, sanitisation, relational validation</td></tr><tr><td>Whole-account import</td><td>JSON; 5 MiB and 200,000 records</td><td>Owner-only API transaction</td><td>version migration, known tables only, ids remapped, tenant forced, invalid rows repaired/dropped, references checked, all-or-nothing write</td></tr><tr><td>Password</td><td>15–128 Unicode code points</td><td>Auth callbacks</td><td>context-word and HIBP check, exact-byte versioned scrypt hashing, generic failure paths; HIBP response is time/size bounded and redirects are refused</td></tr><tr><td>TOTP/recovery code</td><td>Better Auth bounded formats</td><td>Auth plugin</td><td>timed TOTP, lockout, encrypted recovery material, one-time use</td></tr><tr><td>Sign-up/setup/invite/reset values</td><td>Bounded JSON/path/header values</td><td>Auth/API</td><td>first-owner or invite gate, token expiry/hash/revocation, generic lookup behavior</td></tr><tr><td>Provider configuration</td><td>Environment only, not end-user input</td><td>Startup</td><td>safe provider id; absolute HTTPS endpoint; loopback-only HTTP; no embedded credentials; partial configuration fails</td></tr><tr><td>CORS/origin/forwarding headers</td><td>HTTP headers</td><td>Root API hook/proxy</td><td>exact origin allow-list, unsafe cross-site rejection, forwarded IP trusted only in packaged single-proxy shape</td></tr><tr><td>CSP violation report</td><td>bounded CSP/Reporting API JSON</td><td>Public rate-limited API route</td><td>64 KiB, maximum 20 events, origin/directive projection only; URL paths/query/fragment discarded</td></tr><tr><td>Offline snapshot</td><td>Previously authorized API response</td><td>Browser cache layer</td><td>account/user/origin scoped, schema validation, AES-GCM integrity, seven-day expiry, read-only projection</td></tr><tr><td>Environment and numeric settings</td><td>Process environment</td><td>Startup parsers/guard</td><td>bounded integers, explicit boolean grammar, fail-closed production invariants</td></tr></tbody></table><p>There is no runtime XML, LDAP, XPath, GraphQL, WebSocket, email, Markdown/WYSIWYG, LaTeX, archive, image, arbitrary file-upload, CSV/spreadsheet, template, shell-command, JNDI, memcache, WebRTC or media processing entry point.</p><h2 id="sensitive-data-and-retention" tabindex="-1">Sensitive data and retention <a class="header-anchor" href="#sensitive-data-and-retention" aria-label="Permalink to &quot;Sensitive data and retention&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Examples</th><th>Storage/transport</th><th>Retention and disclosure</th></tr></thead><tbody><tr><td>Authentication secret</td><td>password verifier, MFA seed/recovery, session/reset/invite values, provider secrets</td><td>SQLite/env over TLS; restrictive host files; secret-manager responsibility</td><td>sessions fixed at 12h with 30m idle expiry; reset/invite bounded and revocable; password verifiers until identity erasure; never log values</td></tr><tr><td>Identity data</td><td>name, email, memberships, provider subject</td><td>SQLite over TLS</td><td>until identity no longer belongs to an account; account erasure removes eligible identity/control rows</td></tr><tr><td>Tenant confidential data</td><td>schedule, notes, real private names</td><td>SQLite, encrypted operator storage, role-filtered API</td><td>operator policy; owner export; account erasure; old backups/audits follow operator retention/legal hold</td></tr><tr><td>Offline tenant data</td><td>last verified identity/account/snapshot</td><td>AES-GCM IndexedDB</td><td>opt-in; seven-day expiry is physically swept before the next cache access; sign-out/opt-out/device clear/schema upgrade/tamper removes records</td></tr><tr><td>Audit/security metadata</td><td>timestamp, actor/account/action/entity/field names, security outcome/IP</td><td>local JSONL and separately forwarded JSON</td><td>no entity values, credentials or bearer tokens; deployment defines access and retention</td></tr><tr><td>Device preference</td><td>theme, zoom and similar settings</td><td>localStorage</td><td>device-local, not account data/export; explicit device clear</td></tr></tbody></table><p>Every <code>/api/*</code> response receives <code>Cache-Control: no-store</code> and <code>Pragma: no-cache</code>. The SPA contains no advertising, analytics or crash-reporting integration. The only default outbound application call is the HIBP password range lookup during credential creation/change/reset. Enabled identity providers add their documented browser and server exchanges.</p><h2 id="cryptographic-inventory" tabindex="-1">Cryptographic inventory <a class="header-anchor" href="#cryptographic-inventory" aria-label="Permalink to &quot;Cryptographic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Purpose</th><th>Primitive/library</th><th>Key/material</th><th>Lifecycle and migration</th></tr></thead><tbody><tr><td>New password storage</td><td>Node <code>crypto.scrypt</code>, <code>N=2^17,r=8,p=1</code>, 16-byte salt, 64-byte result</td><td>password-derived; random salt</td><td>self-describing <code>scrypt-v1</code> record; parameters can version; legacy Better Auth scrypt verify-only</td></tr><tr><td>Password comparison</td><td>Node <code>timingSafeEqual</code></td><td>stored/derived result</td><td>constant-time after fixed-length derivation</td></tr><tr><td>Breach lookup</td><td>SHA-1 only as required by HIBP k-anonymity protocol</td><td>ephemeral candidate digest; five-character prefix sent</td><td>never used as a verifier or security hash; response padding enabled</td></tr><tr><td>Offline snapshot</td><td>Web Crypto AES-256-GCM, 96-bit random IV and AAD</td><td>non-extractable per-browser random device key</td><td>schema v2; corrupt/expired records and v1 plaintext deleted; device clear destroys key/data</td></tr><tr><td>Invite/reset lookup</td><td>SHA-256 token digest</td><td>CSPRNG token shown once</td><td>expiry, use/revocation and account deletion remove state</td></tr><tr><td>Session/auth/MFA</td><td>Better Auth/Node crypto</td><td><code>SMALLSASS_ACCOUNT_SECRET</code>, session tokens, encrypted backup codes/TOTP state</td><td>32+ character operator secret; rotate to invalidate sessions; secret manager/operator rotation required</td></tr><tr><td>Internal service TLS</td><td>OpenSSL P-256/SHA-256, Node HTTPS and nginx verification</td><td>per-install root-only CA key; API-only leaf key; public CA/leaf</td><td>automatic in Compose; optional for same-host bare metal; configured identities never fall back silently; coordinated renewal/recreation</td></tr><tr><td>Public TLS/provider assertion crypto</td><td>TLS proxy, Node trust store and Better Auth providers</td><td>public certificates/provider metadata</td><td>operator certificate lifecycle; HTTPS-only provider configuration; library updates through lockfile</td></tr></tbody></table><p>No home-grown cipher, ECB, unauthenticated application encryption or client-extractable offline key is used. The operator must maintain a deployment key/certificate inventory covering TLS, storage encryption, secret manager, IdP credentials and backup encryption; this repository cannot observe it.</p><p>Review the inventory annually and after any cryptographic change. Rotate application/provider keys after suspected exposure or trust-boundary/staff changes and at the deployment&#39;s documented interval. Formats deliberately carry versions so new password/KDF and encrypted-cache profiles can coexist during migration. The project will follow maintained Node/Web Crypto/Better Auth primitives, track NIST and OWASP deprecations, and introduce approved post-quantum TLS/signature algorithms only after its platform dependencies provide interoperable production implementations; no custom hybrid cryptography will be added. Re-encryption of operator volumes/backups belongs in that platform&#39;s key rotation plan.</p><p><code>pnpm run security:crypto-inventory</code> automatically discovers cryptographic implementation paths and fails when they differ from the reviewed <a href="crypto-inventory.json">machine-readable inventory</a>. Both green gates run it, so a new primitive or TLS/key-handling path requires an explicit inventory review. SBOM, dependency review and CodeQL cover third-party implementation code that this source path check cannot inspect.</p><h2 id="service-connection-and-work-limits" tabindex="-1">Service connection and work limits <a class="header-anchor" href="#service-connection-and-work-limits" aria-label="Permalink to &quot;Service connection and work limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service/resource</th><th style="text-align:right;">Maximum</th><th>Limit behavior and recovery</th></tr></thead><tbody><tr><td>API accepted sockets</td><td style="text-align:right;">512 per process</td><td>new sockets refused; nginx surfaces upstream failure; client retries must be bounded</td></tr><tr><td>API request/incomplete connection</td><td style="text-align:right;">30 seconds</td><td>Fastify terminates timed-out work; proxy has bounded headroom, never an infinite read timeout</td></tr><tr><td>SQLite</td><td style="text-align:right;">one synchronous connection/process; one API process/file</td><td>waits five seconds on a held lock, then surfaces failure; restart/repair rather than spawning writers</td></tr><tr><td>Password scrypt</td><td style="text-align:right;">2 active + 16 queued per process</td><td>identity-global requests share the queue; overflow fails closed; queue releases after success or failure</td></tr><tr><td>HIBP range service</td><td style="text-align:right;">8 active + 32 queued per process; 5-second call</td><td>identity-global requests share the queue; overflow, timeout, redirect or outage fails password mutation closed</td></tr><tr><td>CSP report ingestion</td><td style="text-align:right;">64 KiB and 20 emitted events/request</td><td>malformed/oversize rejected; excess array entries discarded; normal IP rate limit applies</td></tr><tr><td>OIDC/social provider</td><td style="text-align:right;">bounded by 512 active API requests/process</td><td>strict OIDC discovery/JWKS/user-info failures fail closed with no application retry loop; disable an unstable named social provider</td></tr><tr><td>Backup operation</td><td style="text-align:right;">one in flight</td><td>scheduler skips overlap; shutdown waits for completion before closing SQLite</td></tr></tbody></table><h2 id="security-and-audit-event-inventory" tabindex="-1">Security and audit event inventory <a class="header-anchor" href="#security-and-audit-event-inventory" aria-label="Permalink to &quot;Security and audit event inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Events</th><th>Format/destination</th><th>Sensitive-data rule</th></tr></thead><tbody><tr><td>API request log</td><td>method, route, status, latency and request metadata</td><td>Pino JSON stdout when enabled</td><td>no request/response bodies, cookie or authorization values</td></tr><tr><td>Security log</td><td>auth outcomes, required-auth/MFA/fresh-session rejection, authorization/CSRF denial, projected CSP reports, 429, 500, process failure and session revocation</td><td><code>capacitylens.security</code> JSON stdout</td><td>ids/outcomes and bounded source metadata only; never credential/bearer values, exception details or CSP URL paths/queries</td></tr><tr><td>Mutation audit</td><td>actor, account, action, entity, id and changed field names</td><td>transactional SQLite outbox → fsynced mode-0600 JSONL plus optional <code>capacitylens.audit</code> JSON stdout</td><td>field names only, never field values; stable <code>auditId</code> supports replay deduplication</td></tr><tr><td>Proxy/IdP/platform</td><td>TLS/access/WAF/container/identity/collector events</td><td>deployment-defined separate systems</td><td>operator must classify, redact, restrict, retain and correlate in UTC</td></tr></tbody></table><p>Production requires application audit to remain enabled. Forwarding security events to a separate monitored destination is recommended but optional; its absent attestation produces a warning. The local audit sink latches degradation into deep health. The runbook defines incident preservation and review, but the operator must document retention, access groups, time synchronization and alerts.</p><h2 id="third-parties-and-build-inputs" tabindex="-1">Third parties and build inputs <a class="header-anchor" href="#third-parties-and-build-inputs" aria-label="Permalink to &quot;Third parties and build inputs&quot;">​</a></h2><ul><li>Runtime: Node.js 24, Better Auth, <code>jose</code>, Fastify/server packages, React/UI packages, SQLite in Node, nginx and the HIBP range service; strict OIDC is first-class and named social providers are optional/experimental.</li><li>Build/test: pnpm registry packages, GitHub Actions, CodeQL, Playwright browsers, Vitest, ESLint, Stryker, Gitleaks, Syft/Anchore, Trivy and OWASP ZAP.</li><li><code>pnpm-lock.yaml</code> pins the dependency graph. Docker base images are digest-pinned. GitHub actions are full-commit pinned. Dependabot covers npm, Actions and Docker.</li><li>pnpm&#39;s lifecycle-script policy is fail closed; <code>allowBuilds</code> permits only esbuild&#39;s reviewed platform-binary linker, so a newly introduced dependency install script requires an explicit repository change before it can execute in a clean install.</li><li>Workspace peers are explicit and production deployment uses a dedicated lock/graph. A lockfile-recorded Sonner patch disables only its runtime CSS injector; the identical published stylesheet is built as a self-hosted hashed asset so CSP can continue to forbid style elements.</li><li>Runtime images remove package managers and unused network clients. The Docker build rejects frontend/test packages in the API graph, and all three shipped images are scanned for high/critical CVEs.</li><li>CI performs dependency review, production audit, secret scan (reviewed fixture findings pinned in <code>.gitleaksignore</code>), CodeQL, SBOM generation, container vulnerability scanning, DAST and release provenance. DAST is two-tier: the blocking baseline validates the hardened posture — the configuration the deployment guide recommends — while the out-of-the-box default posture is scanned weekly as a non-blocking published report, documenting rather than asserting its residual surface. The public-repository workflows run automatically on their documented events and remain manually runnable for deliberate reruns.</li></ul>',20)])])}const y=t(d,[["render",n]]);export{h as __pageData,y as default};
